import { create } from 'zustand'

export const NEW_THREAD = Symbol('NEW_THREAD')
export type NewThread = typeof NEW_THREAD
export type ThreadId = string | null | NewThread
/**
 * NOTE: you should just use useThreadId instead of accessing this directly
 */
export const useThreadStore = create<{
	threadId: ThreadId
	setThreadId: (id: ThreadId) => void
	emptyThreadUpdatedAt: Date | null
	setEmptyThreadUpdatedAt: (date: Date) => void
	reset: () => void
	initialized: boolean
	setInitialThreadId: (id: string | null) => void
}>((set, get) => ({
	threadId: null,
	setThreadId: (id: ThreadId) => set(() => ({ threadId: id })),
	emptyThreadUpdatedAt: null,
	initialized: false,
	setEmptyThreadUpdatedAt: (date: Date) =>
		set(() => ({ emptyThreadUpdatedAt: date })),
	setInitialThreadId: (id: string | null) => {
		if (get().initialized) return
		return set(() => ({ threadId: id, initialized: true }))
	},
	reset: () =>
		set(() => ({
			threadId: null,
			emptyThreadUpdatedAt: null,
			initialized: false
		}))
}))

export const useThreadId = (): ThreadId => {
	return useThreadStore((state) => state.threadId)
}

export const useSetThreadId = () => {
	const setThreadId = useThreadStore((state) => state.setThreadId)
	return (threadId: ThreadId) => {
		setThreadId(threadId)
	}
}
